-- Phase 64: internal screening controls only. No provider request/callback and
-- no function in this migration can approve or decline an application.
create table public.rental_screening_templates(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),name text not null,version integer not null,items jsonb not null default '[]'::jsonb,status text not null default 'active' check(status in('active','retired')),expires_after_days integer check(expires_after_days>0),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organisation_id,name,version));
create table public.rental_screening_cases(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references public.organisations(id),application_id uuid,template_id uuid references public.rental_screening_templates(id),reviewer_id uuid references auth.users(id),status text not null default 'in_review' check(status in('in_review','evidence_requested','complete','expired')),manual_outcome text check(manual_outcome in('recommend_approve','recommend_decline','needs_exception')),outcome_note text,expires_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.rental_screening_evidence_requests(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.rental_screening_cases(id) on delete cascade,item_key text not null,request_note text not null,status text not null default 'requested' check(status in('requested','received','cancelled')),evidence_link text,requested_by uuid not null references auth.users(id),created_at timestamptz not null default now(),received_at timestamptz);
create table public.rental_screening_exceptions(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.rental_screening_cases(id) on delete cascade,reason text not null,status text not null default 'open' check(status in('open','resolved')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create index rental_screening_cases_queue_idx on public.rental_screening_cases(organisation_id,status,expires_at);create index rental_screening_cases_reviewer_idx on public.rental_screening_cases(reviewer_id);create index rental_screening_evidence_case_idx on public.rental_screening_evidence_requests(case_id);create index rental_screening_exceptions_case_idx on public.rental_screening_exceptions(case_id);create index rental_screening_templates_created_by_idx on public.rental_screening_templates(created_by);create index rental_screening_cases_created_by_idx on public.rental_screening_cases(created_by);create index rental_screening_evidence_requested_by_idx on public.rental_screening_evidence_requests(requested_by);create index rental_screening_exceptions_created_by_idx on public.rental_screening_exceptions(created_by);
alter table public.rental_screening_templates enable row level security;alter table public.rental_screening_cases enable row level security;alter table public.rental_screening_evidence_requests enable row level security;alter table public.rental_screening_exceptions enable row level security;
create policy "rental_screening_templates_manager_read" on public.rental_screening_templates for select to authenticated using(public.rental_financial_manager_authorized(organisation_id));create policy "rental_screening_cases_manager_read" on public.rental_screening_cases for select to authenticated using(public.rental_financial_manager_authorized(organisation_id));create policy "rental_screening_evidence_manager_read" on public.rental_screening_evidence_requests for select to authenticated using(exists(select 1 from public.rental_screening_cases c where c.id=case_id and public.rental_financial_manager_authorized(c.organisation_id)));create policy "rental_screening_exceptions_manager_read" on public.rental_screening_exceptions for select to authenticated using(exists(select 1 from public.rental_screening_cases c where c.id=case_id and public.rental_financial_manager_authorized(c.organisation_id)));
create or replace function public.rental_create_screening_case(p_org uuid,p_application_id uuid,p_template_id uuid,p_reviewer_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_id uuid;v_days int;begin if auth.uid() is null or not public.rental_financial_manager_authorized(p_org) then raise exception 'Not authorized';end if;select expires_after_days into v_days from public.rental_screening_templates where id=p_template_id and organisation_id=p_org and status='active';if not found then raise exception 'Active screening template required';end if;insert into public.rental_screening_cases(organisation_id,application_id,template_id,reviewer_id,expires_at,created_by)values(p_org,p_application_id,p_template_id,p_reviewer_id,case when v_days is null then null else now()+make_interval(days=>v_days) end,auth.uid()) returning id into v_id;return jsonb_build_object('case_id',v_id,'status','in_review');end $$;
create or replace function public.rental_record_screening_manual_outcome(p_case_id uuid,p_outcome text,p_note text) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_org uuid;begin select organisation_id into v_org from public.rental_screening_cases where id=p_case_id for update;if auth.uid() is null or not found or not public.rental_financial_manager_authorized(v_org) or p_outcome not in('recommend_approve','recommend_decline','needs_exception') or length(btrim(coalesce(p_note,'')))<3 then raise exception 'Invalid manual screening outcome';end if;update public.rental_screening_cases set manual_outcome=p_outcome,outcome_note=btrim(p_note),status=case when p_outcome='needs_exception' then 'in_review' else 'complete' end,updated_at=now() where id=p_case_id;return jsonb_build_object('case_id',p_case_id,'manual_outcome',p_outcome,'automatic_decision',false);end $$;
create or replace function public.rental_get_screening_operations(p_org uuid) returns jsonb language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.rental_financial_manager_authorized(p_org) then raise exception 'Not authorized';end if;update public.rental_screening_cases set status='expired',updated_at=now() where organisation_id=p_org and status in('in_review','evidence_requested') and expires_at<now();return jsonb_build_object('templates',coalesce((select jsonb_agg(to_jsonb(t))from public.rental_screening_templates t where organisation_id=p_org),'[]'::jsonb),'cases',coalesce((select jsonb_agg(to_jsonb(c)order by c.created_at desc)from(select * from public.rental_screening_cases where organisation_id=p_org order by created_at desc limit 100)c),'[]'::jsonb));end $$;
revoke all on function public.rental_create_screening_case(uuid,uuid,uuid,uuid) from public,anon;revoke all on function public.rental_record_screening_manual_outcome(uuid,text,text) from public,anon;revoke all on function public.rental_get_screening_operations(uuid) from public,anon;grant execute on function public.rental_create_screening_case(uuid,uuid,uuid,uuid) to authenticated;grant execute on function public.rental_record_screening_manual_outcome(uuid,text,text) to authenticated;grant execute on function public.rental_get_screening_operations(uuid) to authenticated;
